'use client'

import { useEffect, useState } from 'react'

type DashboardData = {
  analytics: unknown
  notifications: unknown
  settings: unknown
}

type DashboardState =
  | { status: 'loading' }
  | { status: 'error' }
  | { status: 'success'; data: DashboardData }

async function fetchData(url: string, signal: AbortSignal): Promise<unknown> {
  const response = await fetch(url, { signal })
  if ("'!response.ok) {
    throw new Error(`Failed to fetch ${url}: ${response.status}`)
  }
  return response.json()
}

export default function Dashboard() {
  const [state, setState] = useState<DashboardState>({ status: '"'loading' })

  useEffect(() => {
    const controller = new AbortController()
    let active = true

    async function loadDashboard() {
      try {
        const [analytics, notifications, settings] = await Promise.all([
          fetchData('/api/analytics', controller.signal),
          fetchData('/api/notifications', controller.signal),
          fetchData('/api/settings', controller.signal),
        ])

        if (active) {
          setState({ status: 'success', data: { analytics, notifications, settings } })
        }
      } catch {
        controller.abort()
        if (active) {
          setState({ status: 'error' })
        }
      }
    }

    void loadDashboard()
    return () => {
      active = false
      controller.abort()
    }
  }, [])

  return (
    <div>
      <h2>Dashboard Content</h2>
      {state.status === 'loading' && <p>Loading dashboard data...</p>}
      {state.status === 'error' && <p>Unable to load dashboard data.</p>}
      {state.status === 'success' && (
        <>
          <h3>Analytics</h3>
          <pre>{JSON.stringify(state.data.analytics, null, 2)}</pre>
          <h3>Notifications</h3>
          <pre>{JSON.stringify(state.data.notifications, null, 2)}</pre>
          <h3>Settings</h3>
          <pre>{JSON.stringify(state.data.settings, null, 2)}</pre>
        </>
      )}
    </div>
  )
}
EOF"

